from pathlib import Path
import os,json,hashlib
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[2];O=R/'qa/super-director';html=(R/'dist/INK-Street-Fighter-6.html').read_bytes()
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=os.environ['INK_CHROMIUM'],headless=True);p=b.new_page(viewport={'width':1440,'height':1100});errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html.decode());p.wait_for_function('window.INKDuel?.ready');p.locator('.kinetic-launch button').click();p.locator('#fight-practice').click();p.evaluate('SVG_FIGHTER.state.paused=true')
 rows=p.evaluate('''()=>{const A=SVG_FIGHTER,G=A.state,D=INK.SuperDirector,out=[],check=(name,passed,details)=>out.push({name,passed,details});
 function setup(id='ryu'){A.start(id,'ken','training','classic',1);G.paused=true;document.getElementById('dummy').value='idle';document.getElementById('infinite').checked=false;document.getElementById('autohp').checked=false;A.teleport(0,560);A.teleport(1,720);}
 for(const id of INK.Schema.CHARACTERS){setup(id);A.inputMove(0,'SA3');let phases=new Set();for(let i=0;i<240;i++){A.step();for(const e of D.inspect(G).entries)phases.add(e.phase);if(phases.has('finish'))break;}check(id+' super follows real startup and confirmed final contact',phases.has('start')&&phases.has('finish')&&A.fighters[1].hp<10000&&A.fighters[0].super<1,{phases:[...phases],hp:A.fighters[1].hp});}
 setup('ken');A.teleport(0,105);A.teleport(1,1335);A.inputMove(0,'SA1');const phases=new Set();for(let i=0;i<200;i++){A.step();for(const e of D.inspect(G).entries)phases.add(e.phase);}check('Whiffed super never shows a fake finishing hit',!phases.has('finish')&&phases.has('whiff')&&A.fighters[1].hp===10000,{phases:[...phases]});
 setup();document.getElementById('dummy').value='guard';A.inputMove(0,'SA1');let blocked=false,finish=false;for(let i=0;i<200;i++){A.step();for(const e of D.inspect(G).entries){blocked||=e.blocks>0;finish||=e.phase==='finish';}}check('Guarded super counts defense and denies hit-only finisher',blocked&&!finish&&A.fighters[1].hp===10000);
 setup();A.inputMove(0,'SA3');for(let i=0;i<240&&!D.inspect(G).entries.some(e=>e.phase==='finish');i++)A.step();const state=JSON.stringify(D.inspect(G)),hp=A.fighters[1].hp,tick=G.tick;for(let i=0;i<20;i++){A.render();INK.VFX.render(G,.5);}check('Paused redraw does not advance phases or repeat hits',state===JSON.stringify(D.inspect(G))&&G.tick===tick&&A.fighters[1].hp===hp);check('Cinematic framing preserves the stable camera',A.renderCamera() ==='matrix(1 0 0 1 0 0)');
 INK.VFX.settings.reducedMotion=true;INK.VFX.render(G,1);check('Reduced motion suppresses finishing streak layers',[...document.querySelector('[data-super-composition="front"]').children].slice(2).every(n=>n.getAttribute('display')==='none'));INK.VFX.settings.reducedMotion=false;
 A.reset();check('Reset clears cinematic state',D.inspect(G).entries.length===0&&D.inspect(G).events.length===0);return out;}''')
 p.locator('[data-super-close]').click();p.evaluate('SVG_FIGHTER.state.paused=true');p.locator('[data-super="SA3"]').click();p.evaluate('SVG_FIGHTER.render();INK.VFX.render(SVG_FIGHTER.state,1)');p.locator('#game').screenshot(path=str(O/'startup.png'))
 p.evaluate("for(let i=0;i<240&&!INK.SuperDirector.inspect(SVG_FIGHTER.state).entries.some(e=>e.phase==='finish');i++)SVG_FIGHTER.step();SVG_FIGHTER.render();INK.VFX.render(SVG_FIGHTER.state,1)");rows.append({'name':'Actual SA3 control reaches a real finisher','passed':p.evaluate("INK.SuperDirector.inspect(SVG_FIGHTER.state).entries.some(e=>e.phase==='finish')")});p.locator('#game').screenshot(path=str(O/'finish.png'))
 p.set_viewport_size({'width':390,'height':844});rows.append({'name':'Super controls fit narrow viewport','passed':p.locator('#super-coach').evaluate('(e)=>e.getBoundingClientRect().right<=innerWidth+1')});b.close()
for r in rows:print('PASS' if r['passed'] else 'FAIL',r['name'],r.get('details',''))
(O/'playable.json').write_text(json.dumps({'htmlSha256':hashlib.sha256(html).hexdigest(),'rows':rows,'errors':errors},indent=2)+'\n');print(errors);assert all(r['passed'] for r in rows) and not errors
